import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";

import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";

function AppRouter() {
  const [formData, setFormData] = useState({
    incomeCategory: "",
    questionnaire: {},
    spendingPriorities: {},
    budgetLimits: {}
  });

  const updateData = (data) => {
    setFormData(prev => ({
      ...prev,
      ...data
    }));
  };

  /* ✅ categories where priority >= 3 */
  const selectedCategories = Object.keys(formData.spendingPriorities || {})
    .filter(cat => formData.spendingPriorities[cat] >= 3);

  return (
    <Router>
      <Routes>

        {/* 1️⃣ Income */}
        <Route
          path="/"
          element={<IncomeCategory updateData={updateData} />}
        />

        {/* 2️⃣ Questionnaire */}
        <Route
          path="/questionnaire"
          element={<Questionnaire updateData={updateData} />}
        />

        {/* 3️⃣ Spending Priority */}
        <Route
          path="/spending"
          element={<SpendingPriority updateData={updateData} />}
        />

        {/* 4️⃣ Budget Limits */}
        <Route
          path="/budget"
          element={
            <BudgetLimits
              formData={formData}
              categories={selectedCategories}
            />
          }
        />

        {/* fallback */}
        <Route path="*" element={<Navigate to="/" />} />

      </Routes>
    </Router>
  );
}

export default AppRouter;
